/* Operational prototype: role-scoped quotes, negotiated discounts and flexible partial payments. */
const permissionItems=[['bookings','Bookings & calendar'],['discount','Offer discounts / request approval'],['payments','Receive & review payments'],['finance','View finance & invoices'],['inventory','Manage inventory'],['approvals','View approval requests'],['website','Manage website'],['settings','Manage halls, services and pricing']];
const allPermissions=permissionItems.map(x=>x[0]);
function opsState(){if(!data.ops){data.ops={roles:[{name:'Manager',permissions:['bookings','discount','payments','finance','inventory','approvals'],percent:10,amount:25000},{name:'Reception',permissions:['bookings'],percent:0,amount:0},{name:'Cashier',permissions:['payments','finance'],percent:0,amount:0},{name:'Accountant',permissions:['finance'],percent:0,amount:0}],users:[{id:'owner',name:'Venue owner',email:'owner@example.test',role:'Owner',halls:['*'],active:true},{id:'manager',name:'Sara Ahmed',email:'manager@example.test',role:'Manager',halls:['*'],active:true}],approvals:[],deals:{},services:null};save()}return data.ops}
let previewActor='owner',staffTab='users',roleIndex=0,editUserId=null,editingRole=false;
const actor=()=>opsState().users.find(u=>u.id===previewActor&&u.active)||opsState().users[0];
const actorRole=()=>actor().role==='Owner'?{name:'Owner',permissions:allPermissions,percent:100,amount:Infinity}:opsState().roles.find(r=>r.name===actor().role)||{permissions:[],percent:0,amount:0};
const isOwner=()=>actor().role==='Owner';
const can=p=>isOwner()||actorRole().permissions.includes(p);
const hallAllowed=h=>isOwner()||actor().halls.includes('*')||actor().halls.includes(h.id);
function configuredServices(){let s=opsState();if(!s.services){let c=installState.config.venue4||{};s.services=[{id:'chairs',name:'Additional chairs',price:Number(c.v0??150),unit:'Per unit'},{id:'lighting',name:'Special lighting',price:Number(c.v1??18000),unit:'Per event'},{id:'dj',name:'Music / DJ',price:Number(c.v2??25000),unit:'Per event'},{id:'catering',name:'Catering',price:Number(c.v3??1500),unit:'Per guest'}];save()}return s.services}
let quote={qty:{},discount:'0',discountType:'PKR',reason:'',payment:'',key:'QUOTE-'+Date.now()};
function resetQuote(){quote={qty:{},discount:'0',discountType:'PKR',reason:'',payment:'',key:'QUOTE-'+Date.now()+'-'+Math.random().toString(36).slice(2,7)}}
function quoteTotals(h,publicMode=false){let lines=configuredServices().filter(s=>Number(quote.qty[s.id])>0).map(s=>{let qty=s.unit==='Per guest'?+booking.guest:s.unit==='Per event'?1:+quote.qty[s.id];return {...s,qty,total:Math.round(s.price*qty)}});let extras=lines.reduce((n,l)=>n+l.total,0),subtotal=+h.price+extras,value=publicMode?0:Number(quote.discount||0),discount=Math.round(quote.discountType==='Percent'?subtotal*value/100:value);return {lines,extras,subtotal,discount,total:subtotal-discount}}
const quoteFingerprint=(h,t)=>JSON.stringify([quote.key,h.id,booking.date,booking.program,+booking.guest,t.subtotal,t.discount,t.lines.map(l=>[l.id,l.qty,l.total]),quote.reason]);
function discountCap(t){return Math.floor(t.subtotal*Number(actorRole().percent||0)/100)}
function discountApproval(h,t){return opsState().approvals.find(a=>a.fingerprint===quoteFingerprint(h,t)&&a.requester===actor().id&&a.status==='Approved')}
function discountGate(h,t,publicMode){if(!Number.isFinite(t.discount)||t.discount<0||t.discount>t.subtotal)return 'Discount cannot exceed the quotation or be negative.';if(!publicMode&&!hallAllowed(h))return 'You do not have access to this hall.';if(!publicMode&&t.discount>0&&!can('discount'))return 'Your role cannot offer a discount.';if(!publicMode&&t.discount>0&&!quote.reason.trim())return 'Enter a reason for the discount.';if(!publicMode&&t.discount>discountCap(t)&&!discountApproval(h,t))return 'Owner approval is required before continuing.';return ''}
function validateQuote(h,publicMode){if(!Number.isInteger(+booking.guest)||+booking.guest<1||+booking.guest>+h.capacity){toast('Guest count must be within the hall capacity.');return false}let t=quoteTotals(h,publicMode),err=discountGate(h,t,publicMode);if(err){toast(err);return false}return true}
function quoteEditor(h,p,publicMode){let t=quoteTotals(h,publicMode),limit=discountCap(t),err=discountGate(h,t,publicMode),pending=opsState().approvals.find(a=>a.fingerprint===quoteFingerprint(h,t)&&a.requester===actor().id&&a.status==='Pending');return `<div class="config-card"><h3>Event & guest count</h3><p class="muted config-help">${esc(h.name)} · ${esc(p.name)} · capacity ${h.capacity}</p>${payInput('Final guest count','ops-guest',booking.guest,'number',true,`min="1" max="${h.capacity}" step="1"`)}</div><h3 style="margin:18px 0 10px">Optional services</h3><div class="ops-services">${configuredServices().map(s=>`<div class="ops-service"><div><b>${esc(s.name)}</b><small>${money(s.price)} ${esc(s.unit.toLowerCase())}</small></div>${s.unit==='Per unit'?`<label class="field">Quantity<input name="ops-qty-${esc(s.id)}" type="number" min="0" step="1" value="${esc(quote.qty[s.id]||0)}"></label>`:`<label class="pay-check"><input type="checkbox" name="ops-qty-${esc(s.id)}" ${quote.qty[s.id]?'checked':''}>Add</label>`}</div>`).join('')}</div>${!publicMode&&can('discount')?`<section class="config-card" style="margin-top:16px"><h3>Negotiated discount</h3><p class="muted config-help">${isOwner()?'Owner can authorize the final negotiated amount.':`Your limit: ${actorRole().percent}% and ${money(actorRole().amount)} maximum (${money(limit)} on this quote).`}</p><div class="fields">${field('Discount type','ops-discount-type','select',quote.discountType,['PKR','Percent'])}${payInput('Discount value','ops-discount',quote.discount,'number',true,'min="0" step="1"')}<label class="field span2">Reason<textarea name="ops-reason" placeholder="Customer negotiated price, promotion, etc.">${esc(quote.reason)}</textarea></label></div>${t.discount>limit&&!isOwner()?`<div class="note">${discountApproval(h,t)?'Owner approved this exact quote.':pending?'Approval request pending. Switch to Owner to review.':'Above your limit. Request owner approval.'}</div>${!pending&&!discountApproval(h,t)?cfgButton('Request owner approval','ops-request-discount','gold','shield'):''}`:''}</section>`:''}<div class="summary-lines" style="margin-top:15px"><div><span>Hall package</span><b>${money(h.price)}</b></div>${t.lines.map(l=>`<div><span>${esc(l.name)} × ${l.qty}</span><b>${money(l.total)}</b></div>`).join('')}<div><span>Subtotal</span><b>${money(t.subtotal)}</b></div><div><span>Discount</span><b>− ${money(t.discount)}</b></div><div class="total"><span>Final quotation</span><b>${money(t.total)}</b></div></div>${err&&t.discount>0?`<div class="note">${esc(err)}</div>`:''}`}
function submitDiscountRequest(){let h=chosenHall(),t=quoteTotals(h,false);if(!can('discount')||!hallAllowed(h)||isOwner()||!quote.reason.trim()||!Number.isFinite(t.discount)||t.discount<=discountCap(t)||t.discount>t.subtotal){toast('Enter a valid above-limit discount and reason.');return}let fp=quoteFingerprint(h,t);if(opsState().approvals.some(a=>a.fingerprint===fp&&a.requester===actor().id&&a.status==='Pending'))return;opsState().approvals.push({id:'DISC-'+Date.now().toString().slice(-7),requester:actor().id,requesterName:actor().name,hall:h.name,customer:booking.name,subtotal:t.subtotal,discount:t.discount,total:t.total,reason:quote.reason,fingerprint:fp,status:'Pending'});save();render();toast('Discount request sent to owner.')}
function decideDiscount(i,decision){let r=opsState().approvals[i];if(!isOwner()||!r||r.status!=='Pending'||r.requester===actor().id)return false;r.status=decision;r.decidedBy=actor().id;save();return true}
function discountQueue(){let a=opsState().approvals;return card('Booking discount approval requests',`<div class="table-wrap"><table><thead><tr><th>Request / customer</th><th>Manager</th><th>Quote / discount</th><th>Reason</th><th>Status</th><th>Action</th></tr></thead><tbody>${a.map((r,i)=>`<tr><td>${esc(r.id)}<br><small>${esc(r.customer)} · ${esc(r.hall)}</small></td><td>${esc(r.requesterName)}</td><td>${money(r.subtotal)}<br><b>− ${money(r.discount)}</b></td><td>${esc(r.reason)}</td><td>${badge(r.status)}</td><td>${isOwner()&&r.status==='Pending'?cfgButton('Approve','ops-discount-decision:'+i+':Approved','primary sm')+' '+cfgButton('Reject','ops-discount-decision:'+i+':Rejected','danger sm'):'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No negotiated discount requests yet.</td></tr>'}</tbody></table></div><p class="muted config-help">Approval applies only to the exact immutable quote details. Changing guest count, services, price or discount requires a new decision.</p>`)}
function flexibleAmount(h,publicMode){let t=quoteTotals(h,publicMode),recommended=Math.round(t.total*Number(paymentSettings().deposit)/100),v=quote.payment===''?recommended:Number(quote.payment);return {t,recommended,amount:v}}
const fixedPaymentFields=paymentBookingFields;
paymentBookingFields=function(deposit,publicMode){let h=chosenHall(),{t,recommended,amount}=flexibleAmount(h,publicMode);let opts=publicMode?onlineAccounts():staffAccounts(),v=opts.length?amount:0;return `<div class="config-card"><h3>How much is being paid today?</h3><p class="muted config-help">Suggested deposit: ${money(recommended)}. Accept a smaller amount, a larger amount, full payment or no payment today.</p>${payInput('Payment amount (PKR)','ops-payment',v,'number',true,`min="0" max="${t.total}" step="1"`)}<div class="actions" style="margin-top:10px">${cfgButton('Suggested deposit','ops-pay-suggested','outline sm')}${cfgButton('Full payment','ops-pay-full','primary sm')}${cfgButton('Pay later','ops-pay-zero','outline sm')}</div><div class="summary-lines"><div><span>Agreed total</span><b>${money(t.total)}</b></div><div><span>Remaining after verified payment</span><b>${money(Math.max(0,t.total-v))}</b></div></div></div>${v>0?fixedPaymentFields(v,publicMode):'<div class="note">No money is recorded today. The booking remains pending / awaiting payment.</div>'}`};
completeMockPayment=function(fd,h,publicMode){if(!validateQuote(h,publicMode))return false;let t=quoteTotals(h,publicMode),amount=fd['ops-payment']!==undefined?Number(fd['ops-payment']):flexibleAmount(h,publicMode).amount,opts=publicMode?onlineAccounts():staffAccounts(),a=opts.find(x=>x.id===fd['booking-payment-account']);if(!Number.isInteger(amount)||amount<0||amount>t.total){toast('Payment must be between zero and the outstanding balance.');return false}if(amount>0&&!a){toast('Choose an enabled payment method.');return false}if(!publicMode&&amount>0&&!can('payments')){toast('Your role cannot record payments.');return false}let ref=String(fd['booking-payment-reference']||'').trim();if(amount>0&&a?.type!=='Cash at venue'&&!ref){toast('Enter a sample payment reference.');return false}let cash=amount>0&&a?.type==='Cash at venue'&&!publicMode;booking.reference='DEMO-BK-'+Date.now().toString().slice(-7);booking.paymentStatus=cash?'Confirmed':amount>0&&a?.type!=='Cash at venue'?'Payment pending review':'Awaiting deposit';let row=[booking.reference,booking.name,booking.date,h.name,booking.program,booking.paymentStatus,money(t.total)];rows('venue-reservations',initial.bookings).push(row);if(publicMode)rows('venue-publicBookings',initial.bookings).push([...row]);opsState().deals[booking.reference]={reference:booking.reference,hall:h.name,hallId:h.id,customer:booking.name,guests:+booking.guest,lines:t.lines,subtotal:t.subtotal,discount:t.discount,total:t.total,paid:cash?amount:0,claimed:cash?0:amount,status:booking.paymentStatus,payments:cash?[{amount,method:a.label,reference:'Cash received (demo)'}]:[]};if(amount>0&&!cash&&a?.type!=='Cash at venue')paymentClaims().push({booking:booking.reference,method:a.label,amount,reference:ref,status:'Pending review'});save();return true};
const opsConfirmation=paymentBookingConfirmation;
paymentBookingConfirmation=function(h,p){let body=opsConfirmation(h,p),d=opsState().deals[booking.reference];return d?body+`<div class="summary-lines"><div><span>Final booking price</span><b>${money(d.total)}</b></div><div><span>Verified payment</span><b>${money(d.paid)}</b></div><div><span>Awaiting verification</span><b>${money(d.claimed)}</b></div><div class="total"><span>Outstanding balance</span><b>${money(d.total-d.paid)}</b></div></div>${mode==='venue'?btn('Manage booking','ops-view-deal:'+esc(d.reference),'primary'):''}`:body};
function staffPage(){let s=opsState(),r=s.roles[roleIndex]||s.roles[0];return pagehead('Staff & permissions','Create users, assign roles, restrict hall access and configure discount authority.',cfgButton('Add user','ops-user-new','gold','plus'))+`<div class="tabs"><button class="${staffTab==='users'?'active':''}" data-action="ops-staff-tab:users">Users</button><button class="${staffTab==='roles'?'active':''}" data-action="ops-staff-tab:roles">Roles & permissions</button></div>`+(staffTab==='users'?card('Team members',`<div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Hall access</th><th>Status</th><th>Actions</th></tr></thead><tbody>${s.users.map(u=>`<tr><td><b>${esc(u.name)}</b><br><small>${esc(u.email)}</small></td><td>${esc(u.role)}</td><td>${u.halls.includes('*')?'All halls':esc(configuredHalls().filter(h=>u.halls.includes(h.id)).map(h=>h.name).join(', '))}</td><td>${badge(u.active?'Active':'Disabled')}</td><td>${u.role==='Owner'?'Protected owner':cfgButton('Edit','ops-user-edit:'+u.id,'outline sm')+' '+cfgButton(u.active?'Disable':'Enable','ops-user-toggle:'+u.id,'outline sm')}</td></tr>`).join('')}</tbody></table></div><p class="muted config-help">The actual system must use secure invitations and MFA enrollment. No real user account is created here.</p>`):card('Role permissions',`<div class="actions" style="margin-bottom:16px">${s.roles.map((x,i)=>cfgButton(x.name,'ops-role:'+i,i===roleIndex?'primary':'outline'))}${cfgButton('+ New role','ops-role-new','gold')}</div><form id="ops-role-form">${payInput('Role name','role-name',r.name)}<h3 style="margin:16px 0 9px">Allowed actions</h3><div class="ops-perms">${permissionItems.map(([k,l])=>payCheckbox('perm-'+k,l,r.permissions.includes(k))).join('')}</div><h3 style="margin:16px 0 8px">Discount limits</h3><div class="fields">${payInput('Maximum percentage','role-percent',r.percent,'number',true,'min="0" max="100"')}${payInput('Maximum amount (PKR)','role-amount',r.amount,'number',true,'min="0" step="1"')}</div><p class="muted config-help">Both limits apply. Anything above the lower limit requires independent owner approval. The Owner role is protected.</p><button type="submit" class="btn gold" style="margin-top:15px">Save role</button></form>`))}
function userDialog(id){let u=opsState().users.find(x=>x.id===id)||{name:'',email:'',role:'Manager',halls:['*'],active:true};if(u.role==='Owner')return;editUserId=id||null;dialog(id?'Edit staff member':'Create staff member',`<form id="ops-user-form"><div class="fields">${payInput('Full name','user-name',u.name)}${payInput('Email address (demo)','user-email',u.email,'email')}${field('Role','user-role','select',u.role,opsState().roles.map(r=>r.name))}</div><h3 style="margin:16px 0 8px">Hall access</h3>${payCheckbox('hall-all','All halls',u.halls.includes('*'))}<div class="ops-perms" style="margin-top:8px">${configuredHalls().map(h=>payCheckbox('hall-'+h.id,h.name,u.halls.includes(h.id))).join('')}</div><div class="note">The role determines accessible modules and discount limits. Real users receive a secure invitation and enroll MFA.</div></form>`,cfgButton('Cancel','close-dialog','outline')+cfgButton('Save user','ops-user-save','gold'))}
function userSave(){let fm=$('#ops-user-form');if(!fm?.reportValidity())return;let fd=Object.fromEntries(new FormData(fm)),s=opsState(),name=fd['user-name'].trim(),email=fd['user-email'].trim().toLowerCase(),role=fd['user-role'];if(!s.roles.some(r=>r.name===role)||s.users.some(u=>u.email.toLowerCase()===email&&u.id!==editUserId)){toast('Choose a valid role and unique email address.');return}let hs=fd['hall-all']?['*']:configuredHalls().filter(h=>fd['hall-'+h.id]).map(h=>h.id);if(!hs.length){toast('Assign at least one hall.');return}let u=s.users.find(x=>x.id===editUserId);if(u)Object.assign(u,{name,email,role,halls:hs});else s.users.push({id:'user-'+Date.now(),name,email,role,halls:hs,active:true});save();$('#dialog').close();render();toast('Sample staff member saved.')}
function roleSave(fd){let name=fd['role-name'].trim(),percent=Number(fd['role-percent']),amount=Number(fd['role-amount']),s=opsState();if(!name||name.toLowerCase()==='owner'||s.roles.some((r,i)=>i!==roleIndex&&r.name.toLowerCase()===name.toLowerCase())||percent<0||percent>100||amount<0)return false;let old=s.roles[roleIndex].name;s.roles[roleIndex]={name,percent,amount,permissions:permissionItems.filter(([k])=>fd['perm-'+k]).map(([k])=>k)};s.users.filter(u=>u.role===old).forEach(u=>u.role=name);save();return true}
venueDefs.services=def('Services & add-ons','Manage optional services and unit prices.','box',[],[],[],'');
ownerGroups.find(g=>g[0]==='Manage your business')[1].splice(3,0,['services','Services & add-ons','box']);
function servicesPage(){let list=configuredServices();return pagehead('Services & add-ons','Create the optional items staff can add to a booking.',cfgButton('Add service','ops-service-add','gold','plus'))+card('Service catalog',`<form id="ops-services-form"><div class="config-stack">${list.map((s,i)=>`<div class="config-card"><div class="config-card-head"><h3>${esc(s.name||'New service')}</h3>${cfgButton('Remove','ops-service-remove:'+i,'danger sm')}</div><div class="fields three">${payInput('Service name','svc-'+i+'-name',s.name)}${payInput('Price (PKR)','svc-'+i+'-price',s.price,'number',true,'min="0" step="1"')}${field('Charge','svc-'+i+'-unit','select',s.unit,['Per unit','Per guest','Per event'])}</div></div>`).join('')}</div><button class="btn gold" type="submit" style="margin-top:14px">Save service catalog</button></form><p class="muted config-help">Production must retain previous signed quote prices when the catalog changes.</p>`)}
function showDeal(ref){let d=opsState().deals[ref];if(!d)return;if(!can('bookings')&&!can('finance'))return;if(!isOwner()&&!actor().halls.includes('*')&&!actor().halls.includes(d.hallId)){toast('You do not have access to this hall.');return}let due=d.total-d.paid;dialog('Booking '+ref,`<h3>${esc(d.customer)} · ${esc(d.hall)}</h3><p class="muted">${d.guests} guests</p><div class="summary-lines"><div><span>Subtotal</span><b>${money(d.subtotal)}</b></div><div><span>Discount</span><b>${money(d.discount)}</b></div><div><span>Agreed total</span><b>${money(d.total)}</b></div><div><span>Verified payments</span><b>${money(d.paid)}</b></div><div><span>Pending evidence</span><b>${money(d.claimed)}</b></div><div class="total"><span>Balance</span><b>${money(due)}</b></div></div><h3 style="margin:15px 0 8px">Payment history</h3>${d.payments.map(p=>`<div class="record"><div><b>${esc(p.method)}</b><small>${esc(p.reference)}</small></div><b>${money(p.amount)}</b></div>`).join('')||'<p class="muted">No verified payments yet.</p>'}${can('payments')&&due>d.claimed?`<form id="ops-balance-form" data-ref="${esc(ref)}"><h3 style="margin:18px 0 8px">Record another payment</h3>${payInput('Amount (PKR)','balance-amount',due-d.claimed,'number',true,`min="1" max="${due-d.claimed}"`)}<label class="field" style="margin-top:8px">Method<select name="balance-account">${staffAccounts().map(a=>`<option value="${esc(a.id)}">${esc(a.label)}</option>`).join('')}</select></label>${payInput('Sample receipt / transfer reference','balance-reference','DEMO-RCT-001')}<button type="submit" class="btn gold" style="margin-top:12px">Record payment</button></form>`:''}<div class="note">Sample records only. Unverified transfers remain pending.</div>`,cfgButton('Close','close-dialog','outline'))}
function recordBalance(ref,fd){let d=opsState().deals[ref],a=staffAccounts().find(a=>a.id===fd['balance-account']),amount=Number(fd['balance-amount']),reference=String(fd['balance-reference']||'').trim();if(!d||!a||!can('payments')||!Number.isInteger(amount)||amount<=0||amount>d.total-d.paid-d.claimed||!reference)return false;if(a.type==='Cash at venue'){d.paid+=amount;d.payments.push({amount,method:a.label,reference});d.status='Confirmed';for(let key of ['venue-reservations','venue-publicBookings']){let row=rows(key,initial.bookings).find(x=>x[0]===ref);if(row)row[5]='Confirmed'}}else{d.claimed+=amount;paymentClaims().push({booking:ref,method:a.label,amount,reference,status:'Pending review'})}save();return true}
const oldOpsGeneric=generic;
generic=function(c,key){if(key==='venue-staff')return staffPage();if(key==='venue-services')return servicesPage();if(key==='venue-approvals')return discountQueue()+oldOpsGeneric(c,key);return oldOpsGeneric(c,key)};
const opsRecordAction=recordAction;
recordAction=function(key,i,a){let c=configFor(key),r=c&&rows(key,c.rows)[i];if((key==='venue-reservations'||key==='venue-publicBookings')&&r&&opsState().deals[r[0]]&&['View','Edit'].includes(a)){showDeal(r[0]);return}opsRecordAction(key,i,a)};
const permsByPage={dashboard:null,search:'bookings',calendar:'bookings',newBooking:'bookings',reservations:'bookings',publicBookings:'bookings',enquiries:'bookings',proposals:'bookings',planning:'bookings',events:'bookings',finance:'finance',historical:'finance',inventory:'inventory',approvals:'approvals',paymentClaims:'payments',paymentMethods:'owner',staff:'owner',audit:'owner',licensing:'owner',installation:'owner',support:'owner',programs:'settings',pricing:'settings',services:'settings',photos:'website',website:'website'};
function pageAllowed(p){let k=permsByPage[p];return k==='owner'?isOwner():!k||can(k)}
const opsNav=nav;
nav=function(groups){return mode==='venue'?opsNav(groups.map(([label,items])=>[label,items.filter(item=>pageAllowed(item[0]))]).filter(g=>g[1].length)):opsNav(groups)};
const opsRender=render;
render=function(){opsRender();if(mode==='venue'&&!pageAllowed(page)){let main=$('.content');if(main)main.innerHTML=pagehead('Access restricted','Your role does not have access to this page.',btn('Go home','go:dashboard','primary'));else $('#app').innerHTML=switchbar()+pagehead('Access restricted','Your role does not have access to this page.');return}if(mode==='venue'){let right=$('.topright');if(right)right.insertAdjacentHTML('beforeend',`<span class="badge info">${esc(actor().role)}</span>`)}};
const opsSwitch=switchbar;
switchbar=function(){let html=opsSwitch();return html.replace('</div><button class="demo-installer-link"',`</div><label class="preview-role">Preview role<select name="ops-actor">${opsState().users.filter(u=>u.active).map(u=>`<option value="${esc(u.id)}" ${u.id===actor().id?'selected':''}>${esc(u.role==='Owner'?'Owner':u.name+' · '+u.role)}</option>`).join('')}</select></label><button class="demo-installer-link"`)};
const opsAction=action;
action=function(s){if(s.startsWith('pay-review:')){if(!can('payments'))return;let [,i,v]=s.split(':'),r=paymentClaims()[+i];if(r?.status==='Pending review'){let d=opsState().deals[r.booking];if(d){if(v==='verified'&&d.paid+r.amount<=d.total){d.paid+=r.amount;d.payments.push({amount:r.amount,method:r.method,reference:r.reference});d.status='Confirmed'}else if(v==='verified'){toast('Payment exceeds outstanding balance.');return}d.claimed=Math.max(0,d.claimed-r.amount);save()}}return opsAction(s)}if(!s.startsWith('ops-'))return opsAction(s);let [a,i,v]=s.split(':');if(a==='ops-request-discount'){submitDiscountRequest();return}if(a==='ops-discount-decision'){if(decideDiscount(+i,v)){render();toast('Owner decision saved.')};return}if(a==='ops-pay-full'||a==='ops-pay-suggested'||a==='ops-pay-zero'){let t=quoteTotals(chosenHall(),mode==='public');quote.payment=String(a==='ops-pay-full'?t.total:a==='ops-pay-zero'?0:Math.round(t.total*Number(paymentSettings().deposit)/100));render();return}if(a==='ops-view-deal'){showDeal(i);return}if(a==='ops-service-add'&&can('settings')){configuredServices().push({id:'svc-'+Date.now(),name:'',price:0,unit:'Per event'});render();return}if(a==='ops-service-remove'&&can('settings')){configuredServices().splice(+i,1);render();return}if(!isOwner())return;if(a==='ops-staff-tab'){staffTab=i;render()}else if(a==='ops-user-new')userDialog(null);else if(a==='ops-user-edit')userDialog(i);else if(a==='ops-user-save')userSave();else if(a==='ops-user-toggle'){let u=opsState().users.find(u=>u.id===i);if(u&&u.role!=='Owner'){u.active=!u.active;save();render()}}else if(a==='ops-role'){roleIndex=+i;render()}else if(a==='ops-role-new'){opsState().roles.push({name:'New role '+(opsState().roles.length+1),permissions:[],percent:0,amount:0});roleIndex=opsState().roles.length-1;render()}};
document.addEventListener('input',e=>{let n=e.target.name||'',v=e.target.value;if(n==='ops-guest')booking.guest=v;else if(n==='ops-discount')quote.discount=v;else if(n==='ops-reason')quote.reason=v;else if(n==='ops-payment')quote.payment=v;else if(n.startsWith('ops-qty-')&&e.target.type!=='checkbox')quote.qty[n.slice(8)]=Math.max(0,Number(v));else if(n.startsWith('svc-')&&can('settings')){let m=n.match(/^svc-(\d+)-(name|price|unit)$/);if(m)configuredServices()[+m[1]][m[2]]=m[2]==='price'?Number(v):v}},true);
document.addEventListener('change',e=>{let n=e.target.name||'';if(n==='ops-actor'){previewActor=e.target.value;if(mode==='venue'&&!pageAllowed(page))installerGo('venue','dashboard');else render();return}if(n==='ops-discount-type')quote.discountType=e.target.value;else if(n.startsWith('ops-qty-')&&e.target.type==='checkbox')quote.qty[n.slice(8)]=e.target.checked?1:0;else if(!['ops-guest','ops-discount','ops-reason','ops-payment'].includes(n)&&!n.startsWith('ops-qty-'))return;render()},true);
document.addEventListener('submit',e=>{let id=e.target.id;if(!['ops-role-form','ops-services-form','ops-balance-form'].includes(id))return;e.preventDefault();e.stopImmediatePropagation();let fd=Object.fromEntries(new FormData(e.target));if(id==='ops-role-form'&&isOwner()){if(roleSave(fd)){render();toast('Role permissions saved.')}else toast('Enter a unique role name and valid limits.')}else if(id==='ops-services-form'&&can('settings')){if(configuredServices().some(s=>!s.name.trim()||!Number.isFinite(s.price)||s.price<0)){toast('Enter valid service names and prices.');return}save();render();toast('Services saved.')}else if(id==='ops-balance-form'){if(recordBalance(e.target.dataset.ref,fd)){$('#dialog').close();render();toast('Sample payment recorded.')}else toast('Check amount, method and reference.')}},true);
const opsHallAction=action;
action=function(s){if(mode==='venue'&&s.startsWith('cfg-book-select:')){let h=configuredHalls()[+s.split(':')[1]];if(h&&!hallAllowed(h)){toast('You do not have access to this hall.');return}}if(mode==='venue'&&s.startsWith('cfg-slot:')){let h=configuredHalls()[+s.split(':')[1]];if(h&&!hallAllowed(h)){toast('You do not have access to this hall.');return}}opsHallAction(s)};
// Hall scope is used at selection and before submission; public users see only configured public halls.
window.addEventListener('hashchange',()=>{if(mode==='venue'&&page==='newBooking'&&bookingStep===4){bookingStep=0;resetQuote();render()}});
opsState();render();
